import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";

export const GIT_BRANCHES_KIND = "@particle-academy/git_branches";

/** `git_branches` — the branch list, with the current one lifted out. */
export const gitBranchesKind: NodeKindDefinition = {
  name: GIT_BRANCHES_KIND,
  aliases: ["git_branches"],
  category: "io",
  label: "Branches",
  description: "List a working copy's branches and report which one is checked out.",
  icon: "⑂",
  accent: "#f97316",
  inputs: [{ id: "in" }],
  outputs: [{ id: "out" }],
  configSchema: [
    { key: "repo", label: "Repository", type: "text", placeholder: "(host default)" },
    { key: "includeRemote", label: "Include remote branches", type: "switch", default: false },
  ],
  defaultConfig: { includeRemote: false },};

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";
import { resolveWorkingCopy } from "./repo";

/**
 * Branches, with the current one lifted out.
 *
 * `current` is separated because almost every workflow that lists branches then
 * asks "which one am I on" — and finding it means scanning for `current: true`,
 * which is a loop each consumer would otherwise rewrite.
 */
export const gitBranchesExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;
  const repo = resolveWorkingCopy(config);

  const all = ((await repo.branches()) ?? []) as { name: string; current?: boolean; remote?: boolean }[];
  const includeRemote = config.includeRemote === true;
  const branches = includeRemote ? all : all.filter((b) => !b.remote);
  const current = all.find((b) => b.current)?.name ?? null;

  ctx.emit({
    type: "log",
    level: "info",
    nodeId: ctx.node.id,
    message: `${branches.length} branch(es), on ${current ?? "(detached)"}`,
  });

  return {
    __port: "out",
    value: { branches, count: branches.length, current, names: branches.map((b) => b.name) },
  };
};

import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { gitBranchesKind } from "../ui/kind";
import { gitBranchesExecutor } from "./executor";

/**
 * The kind with its TypeScript executor attached — for hosts that EXECUTE on TS.
 *
 * The surface in `ui/kind.ts` deliberately carries no executor: the editor is
 * React on every host, so a PHP project vendors `ui/` and never `js/`. When the
 * two were one file the import dangled on exactly those hosts and the editor
 * build failed — a break that only appeared off the runtime that authored it.
 */
export const gitBranchesRunnableKind: NodeKindDefinition = {
  ...gitBranchesKind,
  executor: gitBranchesExecutor,
};

/**
 * The seam between a workflow node and a LOCAL git working copy.
 *
 * Distinct from the `git_pr_*` nodes' seam on purpose. Those act on a hosted
 * provider (a REST API and a token); these drive `git` in a checkout on disk.
 * The two have different failure modes, different credentials and different
 * blast radius, so they declare different capabilities — a host that wants to
 * read pull requests should not have to hand over a working copy, and a host
 * that hands over a working copy is agreeing to something much larger.
 *
 * ```ts
 * import { registerGitRepoHost } from "@/components/fancy/flow-nodes/git-branches/js/repo";
 * import { GitRepository } from "@particle-academy/fancy-git";
 *
 * registerGitRepoHost({
 *   resolve: (name) => new GitRepository(workspacePathFor(name)),
 * });
 * ```
 *
 * `resolve` takes the config's `repo` name rather than a path, so a graph never
 * carries a filesystem path an author could point anywhere. The host decides
 * what a name maps to; the node cannot reach outside what the host allows.
 *
 * This file is duplicated in each local-repo node. That is on purpose: a
 * vendored node is meant to be self-contained and editable in place, so a node
 * you copy in should not depend on another node you did not.
 */

/** The subset of `fancy-git`'s `GitRepository` these nodes use. */
export type GitWorkingCopy = {
  info(): Promise<unknown>;
  status(): Promise<unknown>;
  log(query?: { ref?: string; limit?: number; skip?: number }): Promise<unknown[]>;
  diff(query?: { from?: string; to?: string; staged?: boolean; paths?: string[] }): Promise<unknown>;
  branches(): Promise<unknown[]>;
  checkout(target: string, options?: { propose?: boolean }): Promise<unknown>;
  push(remote?: string, branch?: string, options?: { propose?: boolean }): Promise<unknown>;
  pull(remote?: string, branch?: string, options?: { propose?: boolean }): Promise<unknown>;
};

export type GitRepoHost = {
  /** Map a config `repo` name to a working copy. Return null to refuse. */
  resolve(repo: string | undefined): GitWorkingCopy | null;
};

let host: GitRepoHost | null = null;

/** Install the host. Returns an unregister function. */
export function registerGitRepoHost(next: GitRepoHost): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getGitRepoHost(): GitRepoHost | null {
  return host;
}

/**
 * Resolve the working copy this node acts on.
 *
 * Fails loudly at every step. A node that cannot reach a repository must not
 * return "nothing to do" — on a queue worker that is a green run that never
 * pushed the branch someone was waiting for.
 */
export function resolveWorkingCopy(config: Record<string, unknown>): GitWorkingCopy {
  const current = getGitRepoHost();
  if (!current) {
    throw new Error(
      "git: no repository host registered. Call registerGitRepoHost({ resolve }) with a " +
        "fancy-git GitRepository factory — the node has no filesystem access of its own and must not invent any.",
    );
  }

  const repo = config.repo === undefined || config.repo === null ? undefined : String(config.repo);
  const workingCopy = current.resolve(repo);

  if (!workingCopy) {
    throw new Error(
      `git: the host refused to resolve repository ${repo ? `"${repo}"` : "(default)"}. ` +
        "Register it with the host, or correct the node's `repo`.",
    );
  }

  return workingCopy;
}

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";
import { resolveWorkingCopy } from "./repo";

/**
 * Switch the working copy to a branch or revision.
 *
 * Mutating, so it honours `propose`: fancy-git returns an OperationProposal
 * instead of performing the checkout, and the node routes it to `proposed` for
 * a human to approve. Agents propose, humans confirm — a workflow that moves
 * someone's working copy under them is exactly the case that wants a pause.
 */
export const gitCheckoutExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;
  const repo = resolveWorkingCopy(config);

  const target = String(config.target ?? "").trim();
  if (!target) {
    throw new Error("git_checkout: needs a `target` branch or revision. Refusing to guess.");
  }

  const propose = config.propose === true;
  const result = await repo.checkout(target, { propose });

  // A proposal is the RESULT, not a failure: the node did its job, and the
  // decision belongs to whoever reviews it.
  if (propose) {
    ctx.emit({
      type: "log",
      level: "info",
      nodeId: ctx.node.id,
      message: `proposed checkout of ${target} (not performed)`,
    });
    return { __port: "proposed", value: { target, proposal: result ?? null } };
  }

  ctx.emit({ type: "log", level: "info", nodeId: ctx.node.id, message: `checked out ${target}` });

  return { __port: "done", value: { target } };
};

